前言设置地图以及调用搜索地点服务
&lt;script setup&gt;
import axios from &quot;axios&quot;;
import &#123; ref, onMounted, onUnmounted &#125; from &quot;vue&quot;;
import AMapLoader from &quot;@amap/amap-jsapi-loader&quot;;

let map = null;
const loading = ref(false)

const getHospital = async () =&gt; &#123;
  loading.value = true;
  let hospitalList = [];
  let clinicList = [];
  let page = 1;
  while (true) &#123;
    const &#123; data: res &#125; = await axios.get(`https://restapi.amap.com/v3/place/text?keywords=医院&amp;city=430100&amp;offset=50&amp;page=$&#123;page&#125;&amp;key=1c75af4f449f301bacd944e0a9855dae&amp;extensions=all`)
    hospitalList = hospitalList.concat(res.pois);
    page++;
    if (res.pois.length &lt; 50) &#123;
      break;
    &#125;
  &#125;
  page = 1;
  while (true) &#123;
    const &#123; data: res &#125; = await axios.get(`https://restapi.amap.com/v3/place/text?keywords=诊所&amp;city=430100&amp;offset=50&amp;page=$&#123;page&#125;&amp;key=1c75af4f449f301bacd944e0a9855dae&amp;extensions=all`)
    clinicList = clinicList.concat(res.pois);
    page++;
    if (res.pois.length &lt; 50) &#123;
      break;
    &#125;
  &#125;
  loading.value = false;
  return [hospitalList, clinicList]
&#125;

const initMap = async () =&gt; &#123;
  const AMap = await AMapLoader.load(&#123;
    key: &quot;25304e4dd58635d7b98eaafe0f58e786&quot;, //&quot;, // 申请好的Web端开发者Key，首次调用 load 时必填
    version: &quot;2.0&quot;, // 指定要加载的 JSAPI 的版本，缺省时默认为 1.4.15
    plugins: [], // 需要使用的的插件列表，如比例尺&#39;AMap.Scale&#39;等
  &#125;);
  map = new AMap.Map(&quot;container&quot;, &#123;
    viewMode: &quot;3D&quot;, // 是否为3D地图模式
    zoom: 11, // 初始化地图级别
    center: [116.397428, 39.90923], // 初始化地图中心点位置
  &#125;);

  // await getHospital();

&#125;

onMounted(async () =&gt; &#123;
  await initMap();
&#125;);

onUnmounted(() =&gt; &#123;
  map?.destroy();
&#125;);
&lt;/script&gt;

&lt;template&gt;
  &lt;div id=&quot;container&quot;&gt;&lt;/div&gt;
&lt;/template&gt;

&lt;style scoped&gt;
#container &#123;
  width: 100%;
  height: 100%;
&#125;
&lt;/style&gt;
